/* eslint-disable no-nested-ternary */
import { Tooltip } from 'antd';
import React, { memo, useMemo, useCallback } from 'react';
import styled from 'styled-components';
import { compactNotation } from 'Utils/helpers/commonUtils';

const PercentChange = styled.div`
  padding: 1px 4px;
  background-color: ${({ negative, value }) => (value ? negative ?  'rgba(244, 88, 76, 0.08)' : 'rgba(50, 191, 138, 0.08)' : '')};
  color: ${({ negative }) => (negative ? '#F4584C' : '#32BF8A')};
  border-radius: 16px;
  line-height: 0.6875rem;
  font-size: 0.6875rem;
`;

const Box = memo(({
  subtitle,
  percentageChange,
  valueThisPeroidString,
  mainKey,
  selectedBox,
  _valKey,
  handleClick,
  handleBoxClick,
  _boxIndex = -1,
  tooltipText,
  valueUnit,
}) => {  
  const getBoxValue = useCallback((data) => {
    if (
      mainKey === 'Crashes' ||
      mainKey === 'Rage Taps' ||
      mainKey === 'Screen Visits'
    ) {
      if (subtitle === 'Frequency' || subtitle === 'Average') {
        const value = parseFloat(data);
        return value > 0
          ? data.includes('%')
            ? `${value.toFixed(2)}%`
            : value.toFixed(2)
          : value;
      }
    }
    return data;
  }, [mainKey, subtitle]);

  const tooltipContent = useMemo(() => (
    <>
      <b>{getBoxValue(valueUnit)}</b>{' '}
      {tooltipText}
    </>
  ), [getBoxValue, tooltipText, valueUnit]);

  const percentContent = useMemo(() => {
    const percentageChangeRounded = Math.floor(percentageChange);
    if (!Number.isNaN(percentageChangeRounded)) {
      const isNotNegation = percentageChangeRounded !== Infinity && percentageChangeRounded !== 0;
      return (
        <PercentChange
          negative={
            mainKey === 'Crashes' || mainKey === 'Rage Taps'
              ? Number(percentageChangeRounded) > 0
              : Number(percentageChangeRounded) < 0
          }
          value={isNotNegation}
        >
          {isNotNegation ? `${ percentageChangeRounded > 0 ? '+' : '' }${compactNotation(percentageChange, 1)}%` : ''}
        </PercentChange>
      );
    }
    return null;
  }, [mainKey, percentageChange]);
  return (
    // eslint-disable-next-line jsx-a11y/click-events-have-key-events
    <div
      role="button"
      tabIndex={-1}
      onClick={async (e) => {
        e.preventDefault();
        e.persist();
        if (_valKey) handleClick(_valKey, mainKey);
        handleBoxClick(e, mainKey);
      }}
      className={
        selectedBox?.attrOfSmallBox === _valKey
          ? `stat-flex ${_boxIndex > -1 ? `stat-flex-${_boxIndex}` : ''} active`
          : `stat-flex ${_boxIndex > -1 ? `stat-flex-${_boxIndex}` : ''}${
              selectedBox?.mainKey === mainKey ? ' inactive' : ''
            }`
      }
    >
      <Tooltip title={tooltipContent} placement="bottom" align={{offset: [0, -5]}}>
        <div className="sub-header">
          <div className="stat-title">{subtitle}</div>
          {percentContent}
        </div>
        <div className="stat-box-body">
          <h2>{getBoxValue(valueThisPeroidString)}</h2>
        </div>
      </Tooltip>
    </div>
  );
});
export default Box;
