import React from 'react';
import { InfoCircleOutlined } from '@ant-design/icons';
import { Card, Tooltip } from 'antd';
import cs from 'classnames'

const DummyBoxes = ({
  selectedBox,
  selectedTab,
  matchedIconsActive,
  matchedImagesNotActive,
  statBoxes
}) => {
  const titleErrOrLoader = typeof statBoxes === 'string' ? 'Error' : <span className='loading-text'>loading...</span>
  return [
    'Sessions',
    'Users',
    'Crashes',
    'Rage Taps',
    'Time in App',
    'Screen Visits',
  ].map((v, i) => (
      <Card
        style={{ cursor: 'not-allowed' }}
        key={i}
        className={cs(
          selectedBox?.mainKey === v
            ? v === 'Sessions'
              ? 'box-item card-mini card-active-box'
              : 'box-item  card-active-box'
            : v === 'Sessions'
            ? 'box-item card-mini'
            : 'box-item',
          { disabled: [ 'sessionsList', 'aiSessionsList' ].includes( selectedTab ) }
        )}
        title={
          <div className='overview-card-heading'>
            <div className='icon-box'>
              <img
                alt=''
                src={
                  selectedBox?.mainKey === v
                    ? matchedIconsActive[v]
                    : matchedImagesNotActive[v]
                }
              />
            </div>
            <span>{v}</span>
            <Tooltip title={titleErrOrLoader}>
              <InfoCircleOutlined />
            </Tooltip>
          </div>
        }
      >
        {v === 'Sessions'
          ? ['Count'].map((val, key) => (
              <div key={key} className='stat-flex'>
                <div className='sub-header'>
                  <div className='stat-title'>{val}</div>
                </div>
                <div className='stat-box-body'>
                  <h5>{titleErrOrLoader}</h5>
                </div>
              </div>
            ))
          : ['Total', 'Average'].map((val, key) => (
              <div key={key} className='stat-flex'>
                <div className='sub-header'>
                  <div className='stat-title'>
                    {v === 'Crashes' && val === 'Average'
                      ? 'Frequency'
                      : v === 'Users' && val === 'Average'
                      ? 'New'
                      : val}
                  </div>
                </div>
                <div className='stat-box-body'>
                  <h5>{titleErrOrLoader}</h5>
                </div>
              </div>
            ))}
      </Card>
    ));
}

export default DummyBoxes
