/* eslint-disable no-param-reassign */
import React, { useMemo } from 'react';
// import { InfoCircleOutlined } from '@ant-design/icons';
import { Card } from 'antd';
import cs from 'classnames';
import { formatNumberWithCommas } from 'Utils/helpers/numberFormatter';
import { useIsAppType } from 'hooks/useIsAppType';
import Box from './Box';

const IconUsers = '/static/users-icon-boxes.svg';
const IconRagetaps = '/static/ragetaps-icon-boxes.svg';
const IconTime = '/static/time-icon-boxes.svg';
const IconScreen = '/static/screen-icon-boxes.svg';
const IconCrashed = '/static/crashed-icon-boxes.svg';

const totalSVG = (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="7"
    height="9.333"
    viewBox="0 0 7 9.333"
  >
    <path
      d="M64.888,9.333H59.056a.582.582,0,0,1-.475-.92l2.675-3.755L58.58.921A.582.582,0,0,1,59.055,0h5.834a.583.583,0,0,1,.583.582V1.747H64.3V1.165H60.188L62.446,4.32a.582.582,0,0,1,0,.676L60.186,8.169H64.3V7.583h1.167V8.751A.583.583,0,0,1,64.888,9.333Z"
      transform="translate(-58.471 0)"
    />
  </svg>
);

const averageSVG = (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="9.539"
    height="9.539"
    viewBox="0 0 9.539 9.539"
  >
    <path
      d="M9.334.2a.7.7,0,0,0-.987,0l-.978.978A4.429,4.429,0,0,0,1.182,7.369L.2,8.347a.7.7,0,0,0,.987.987l.978-.978A4.429,4.429,0,0,0,8.356,2.169l.978-.978A.7.7,0,0,0,9.334.2Zm-7.6,4.565A3.035,3.035,0,0,1,6.364,2.187L2.187,6.364A3.017,3.017,0,0,1,1.733,4.769Zm6.072,0A3.035,3.035,0,0,1,3.174,7.351L7.351,3.174A3.018,3.018,0,0,1,7.8,4.769Z"
      transform="translate(0 0)"
    />
  </svg>
);
const DoubleInfoBox = ({
  dataOfABoxes,
  mainKey,
  handleBoxClick,
  handleValuesByName,
  selectedBox,
  graphSelectedVal,
  uniqueUserBox,
  selectedTab,
}) => {
  const isWebApp = useIsAppType( 'web' );
  const handleClick = (keyVal, key) => {
    selectedBox.attrOfSmallBox = keyVal;
    selectedBox.mainKey = key;
    selectedBox.tooltip = dataOfABoxes[keyVal].tooltip_info;
    selectedBox.graph_info = dataOfABoxes[keyVal].graph_name;
    selectedBox.graph_type = graphSelectedVal && graphSelectedVal.display;
    const payload = {
      dropName: 'selectedBox',
      data: selectedBox,
    };
    handleValuesByName(payload);
  };
  const arryOf = Object.keys(dataOfABoxes);
  if (mainKey === 'Users') {
    if (uniqueUserBox) dataOfABoxes.Total = uniqueUserBox;
    else
      dataOfABoxes.Total = {
        box_name: 'Users',
        graph_name: 'Number of unique users',
        graph_type: 'Stacked line chart',
        percentage_change_string: '',
        value_this_period_string: <small className='loading-text'>loading...</small>,
        value_this_period_number: 0,
        tooltip_info:
          'Number of distinct users that used the app at least once',
        agg_l: [
          {
            table: 'session',
            attribute: 'session_unique_user_count',
            operator: '',
          },
        ],
      };
  }

  const getIconSrc = useMemo(() => {
    switch (mainKey) {
      case 'Users':
        return IconUsers;
      case 'Crashes':
        return IconCrashed;
      case 'Rage Taps':
        return IconRagetaps;
      case 'Time in App':
        return IconTime;
      default:
        return IconScreen;
    }
  }, [mainKey]);

  return (
    <Card
      style={{ cursor: 'default', maxWidth: isWebApp ? '100%' : null }}
      data-intercom-target={`Analytics Card ${mainKey}`}
      className={cs('box-item', {
        'card-active-box':
          selectedBox?.mainKey === mainKey &&
          selectedTab === 'sessionStatistics',
      })}
      title={
        <div className="overview-card-heading">
          <div className="icon-box">
            <img src={getIconSrc} height={35} width={35} alt="" />
          </div>
          <span>{mainKey}</span>
          {/* <Tooltip title={selectedBox?.mainKey === mainKey ? dataOfABoxes[selectedBox.attrOfSmallBox].tooltip_info : dataOfABoxes?.Total?.tooltip_info}>
            <InfoCircleOutlined />
          </Tooltip> */}
        </div>
      }
    >
      {arryOf &&
        arryOf.map((v, i) => {
          const valuesOfBox = dataOfABoxes[v];
          const values = valuesOfBox;
          const percentageChange = 
            (100 *
            ((values.value_this_period_number -
              values.value_previous_period_number) /
              values.value_previous_period_number));
          const SVGIcon = v === 'Average' ? averageSVG : totalSVG;
          const hasUnitValue = v === 'Average' || v === 'Frequency' || values.box_name === 'Time in app';
          const valueUnit = `${ hasUnitValue ? values.value_this_period_string : formatNumberWithCommas(values.value_this_period_number)}`;
          return values ? (
            <Box
              key={i}
              subtitle={v}
              percentageChange={percentageChange}
              valueThisPeroidString={values.value_this_period_string}
              valueUnit={valueUnit}
              SVGIcon={SVGIcon}
              _valKey={v}
              mainKey={mainKey}
              handleClick={handleClick}
              selectedBox={selectedBox}
              handleBoxClick={handleBoxClick}
              _boxIndex={i + 1}
              tooltipText={values.tooltip_info}
            />
          ) : (
            ''
          );
        })}
      <style>
        {`
           .ant-card-head {
             background-color: ${
               [ 'sessionsList', 'aiSessionsList' ].includes( selectedTab ) ? '#fff !important' : 'inherit'
             }
           }
          `}
      </style>
    </Card>
  );
};

export default DoubleInfoBox;
