const WebAppIgnoredBox = [
  'Crashes',
]

const OverviewBoxes = () => {
  const dispatch = useDispatch();
  const { callGraphApi } = useSessionAnalyticsAPI();
  const isWebApp = useIsAppType( 'web' );
  const {
    statsBoxes: statBoxesResponse,
    uniqueUserBox,
    dropValues,
    selectedBox,
    graphSelectedVal,
    selectedTab,
  } = useSelector((state) => state.sessionStatisticsReducer);

  const statBoxes =
  statBoxesResponse &&
  // eslint-disable-next-line no-nested-ternary
  (statBoxesResponse.success
    ? statBoxesResponse.data && statBoxesResponse.data.boxes
    : statBoxesResponse.error
    ? statBoxesResponse.error.message
    : 'error');

  const handleBoxClick = async (e) => {
    e.preventDefault();
    const { mainKey } = selectedBox;
    const { attrOfSmallBox } = selectedBox;
    const aggregationList = statBoxes[mainKey][attrOfSmallBox].agg_l[0];
    const graphDisplayVal = selectedBox.graph_type;
    const graphArr = mapGraphDToAttribute[graphDisplayVal];
    const payloadGraph = {
      dropName: 'series_plot_options',
      data: graphTypeObj[graphArr],
    };
    const payload = {
      dropName: 'aggregation_list',
      data: aggregationList,
    };
    await dispatch(handleValuesByName(payloadGraph));
    dispatch(handleValuesByName(payload));
    callGraphApi({ agg_list: statBoxes[mainKey][attrOfSmallBox].agg_l[0] });
    dispatch(
      fetchPlanHatApi({
        action: 'Metric checked on session analytics',
        info: {
          'Metric type': mainKey,
          description:
            'when they click on one of the boxes at the top, e.g. users',
        },
      })
    );
  };

  const handleValuesByNameClick = (payload) => dispatch(handleValuesByName(payload))

  return (
    <OverviewBoxesWrapper>
      <BoxesWrapper>
        {statBoxes?.Sessions ? (
          map(statBoxes, (_val, _key) => {
            if ( isWebApp && WebAppIgnoredBox.includes(_key) ) return null
            return Object.keys(_val).length === 1 ? (
              <InfoBox
                dataOfABox={_val}
                handleBoxClick={handleBoxClick}
                mainKey={_key}
                handleValuesByName={handleValuesByNameClick}
                selectedBox={selectedBox}
                graphSelectedVal={graphSelectedVal}
                selectedTab={selectedTab}
              />
            ) : (
              <DoubleInfoBox
                dataOfABoxes={_val}
                key={_key}
                mainKey={_key}
                handleBoxClick={handleBoxClick}
                dropValues={dropValues}
                handleValuesByName={handleValuesByNameClick}
                selectedBox={selectedBox}
                graphSelectedVal={graphSelectedVal}
                uniqueUserBox={uniqueUserBox}
                selectedTab={selectedTab}
                showPercentDifference
              />
            )
          })
        ) : (
          <DummyBoxes
            selectedBox={selectedBox}
            selectedTab={selectedTab}
            matchedIconsActive={matchedIconsActive}
            matchedImagesNotActive={matchedImagesNotActive}
            statBoxes={statBoxes}
            showPercentDifference
          />
        )}
      </BoxesWrapper>
    </OverviewBoxesWrapper>
  );
};
export default OverviewBoxes;
